import React, { useState, useEffect } from 'react';
import { Sun, Moon, Phone } from 'lucide-react';
import academyLogo from '../assets/logovighnaviacademy.png';

export default function Header({ setActiveScreen }) {
  const [isDarkMode, setIsDarkMode] = useState(true);

  // Initialize theme from document or localStorage
  useEffect(() => {
    const savedTheme = localStorage.getItem('theme');
    const systemPrefersDark = window.matchMedia('(prefers-color-scheme: dark)').matches;

    if (savedTheme === 'light') {
      setIsDarkMode(false);
      document.documentElement.classList.remove('dark');
    } else if (savedTheme === 'dark' || (!savedTheme && systemPrefersDark)) {
      setIsDarkMode(true);
      document.documentElement.classList.add('dark');
    }
  }, []);

  const toggleTheme = () => {
    if (isDarkMode) {
      document.documentElement.classList.remove('dark');
      localStorage.setItem('theme', 'light');
      setIsDarkMode(false);
    } else {
      document.documentElement.classList.add('dark');
      localStorage.setItem('theme', 'dark');
      setIsDarkMode(true);
    }
  };

  return (
    <header className="w-full border-b transition-colors duration-300 bg-neutral-950 text-neutral-300 border-neutral-800">
      {/* Top Notification / Ticker Bar */}
      <div className="border-b py-2 px-4 text-xs transition-colors duration-300 bg-black border-neutral-800 text-neutral-400">
        <div className="max-w-7xl mx-auto flex items-center justify-between">
          <div className="flex items-center space-x-3">
            <span className="inline-flex items-center space-x-1.5 font-semibold text-white">
              <span className="w-2 h-2 rounded-full bg-white animate-pulse"></span>
              <span>Admissions & Bookings Open</span>
            </span>
            <span className="hidden sm:inline text-neutral-700">|</span>
            <span className="hidden sm:inline text-neutral-400">Wisdom. Knowledge. Success.</span>
          </div>

          <div className="flex items-center space-x-4">
            <button
              onClick={() => setActiveScreen && setActiveScreen('contact')}
              className="inline-flex items-center space-x-1.5 text-neutral-300 hover:text-white transition-colors"
            >
              <Phone className="w-3 h-3 text-neutral-400" />
              <span>Support: +91 93906 42779</span>
            </button>
          </div>
        </div>
      </div>

      {/* Main Navigation Bar */}
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-3.5 flex items-center justify-between">
        {/* Brand Logo & Title */}
        <div 
          onClick={() => setActiveScreen && setActiveScreen('home')} 
          className="flex items-center space-x-3.5 cursor-pointer group"
        >
          <img
            src={academyLogo}
            alt="Vighnavi Academy Logo"
            className="h-10 w-auto object-contain transition-transform group-hover:scale-105"
            onError={(e) => {
              // Graceful fallback if image path fails
              e.currentTarget.style.display = 'none';
            }}
          />
          <div className="flex flex-col">
            <span className="text-lg font-extrabold tracking-tight text-white leading-tight">
              VIGHNAVI <span className="font-light text-neutral-400">ACADEMY</span>
            </span>
            <span className="text-[10px] uppercase tracking-widest text-neutral-400">
              Technical Excellence
            </span>
          </div>
        </div>

        {/* Right Section: Navigation Links & Black/White Theme Toggle */}
        <div className="flex items-center space-x-6">
          <nav className="hidden md:flex items-center space-x-6 text-sm font-medium">
            <button
              onClick={() => setActiveScreen && setActiveScreen('home')}
              className="text-neutral-300 hover:text-white transition-colors"
            >
              Home
            </button>
            <button
              onClick={() => setActiveScreen && setActiveScreen('courses')}
              className="text-neutral-300 hover:text-white transition-colors"
            >
              Courses
            </button>
            <button
              onClick={() => setActiveScreen && setActiveScreen('contact')}
              className="text-neutral-300 hover:text-white transition-colors"
            >
              Contact
            </button>
          </nav>

          {/* Black & White Theme Toggle Icon */}
          <button
            onClick={toggleTheme}
            aria-label="Toggle Black and White Theme"
            title={isDarkMode ? 'Switch to Light Theme' : 'Switch to Dark Theme'}
            className="p-2 rounded-xl border transition-all duration-200 focus:outline-none focus:ring-2 focus:ring-neutral-400 bg-neutral-900 border-neutral-700 text-white hover:bg-neutral-800"
          >
            {isDarkMode ? (
              <Sun className="w-4 h-4 text-white hover:rotate-45 transition-transform duration-300" />
            ) : (
              <Moon className="w-4 h-4 text-black hover:-rotate-12 transition-transform duration-300" />
            )}
          </button>
        </div>
      </div>
    </header>
  );
}
